mapper.select:
select w.*,m.username,m.registration_time
from withdraw w
left join member m on w.member_id = m.id
left join coin c on w.coin_id = c.id


        w.member_id = #{memberId}


        w.hash = #{screen.hash}


        w.status = #{screen.status}


        w.address = #{screen.address}


        c.unit= #{screen.unit}


        and ( m.username like concat('%',#{screen.account},'%') or m.real_name like concat('%',#{screen.account},'%') )


        and m.inviter_id = #{screen.inviterId}


order by w.add_time desc

select a.unit , sum(b.total_amount) as amount,sum(b.fee) as total_fee from withdraw b,coin a
where a.name = b.coin_name and date_format(b.deal_time,'%Y-%m-%d') = #{dateStr}
  and b.status = 3 group by a.unit
